package ru.zhukhly.bank;
import android.app.*;
import android.graphics.*;
import android.view.*;
import android.widget.*;
final class CropEditor extends View {
 final Bitmap source; final Paint paint=new Paint(3); final float[] corners={.08f,.08f,.92f,.08f,.92f,.92f,.08f,.92f}; final RectF bounds=new RectF(); int active=-1;
 CropEditor(android.content.Context c,Bitmap b){super(c);source=b;setBackgroundColor(0xff10141b);}
 protected void onDraw(Canvas c){float scale=Math.min((float)getWidth()/source.getWidth(),(float)getHeight()/source.getHeight());float w=source.getWidth()*scale,h=source.getHeight()*scale;bounds.set((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2);paint.setColor(Color.WHITE);c.drawBitmap(source,null,bounds,paint);Path p=new Path();for(int i=0;i<4;i++){float x=x(i),y=y(i);if(i==0)p.moveTo(x,y);else p.lineTo(x,y);}p.close();paint.setColor(0x3349e6ad);paint.setStyle(Paint.Style.FILL);c.drawPath(p,paint);paint.setColor(0xff49e6ad);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(4);c.drawPath(p,paint);paint.setStyle(Paint.Style.FILL);for(int i=0;i<4;i++){c.drawCircle(x(i),y(i),18,paint);paint.setColor(Color.WHITE);c.drawCircle(x(i),y(i),9,paint);paint.setColor(0xff49e6ad);}}
 float x(int i){return bounds.left+corners[i*2]*bounds.width();}float y(int i){return bounds.top+corners[i*2+1]*bounds.height();}
 public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()==0){float best=Float.MAX_VALUE;for(int i=0;i<4;i++){float d=(float)Math.hypot(x(i)-e.getX(),y(i)-e.getY());if(d<best){best=d;active=i;}}}if((e.getAction()==0||e.getAction()==2)&&active>=0&&bounds.width()>0){corners[active*2]=Math.max(0,Math.min(1,(e.getX()-bounds.left)/bounds.width()));corners[active*2+1]=Math.max(0,Math.min(1,(e.getY()-bounds.top)/bounds.height()));invalidate();}if(e.getAction()==1||e.getAction()==3)active=-1;return true;}
 Bitmap crop(){float[] p=corners.clone();for(int i=0;i<8;i++)p[i]*=i%2==0?source.getWidth():source.getHeight();int w=Math.max(32,(int)Math.max(Math.hypot(p[2]-p[0],p[3]-p[1]),Math.hypot(p[4]-p[6],p[5]-p[7]))),h=Math.max(32,(int)Math.max(Math.hypot(p[6]-p[0],p[7]-p[1]),Math.hypot(p[4]-p[2],p[5]-p[3])));Matrix m=new Matrix();if(!m.setPolyToPoly(p,0,new float[]{0,0,w,0,w,h,0,h},0,4))return source;Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(Color.WHITE);c.drawBitmap(source,m,new Paint(3));return b;}
 static void show(Activity a,Bitmap b,java.util.function.Consumer<Bitmap> save){CropEditor editor=new CropEditor(a,b);LinearLayout layout=new LinearLayout(a);layout.setOrientation(1);TextView hint=new TextView(a);hint.setText("Перетащите четыре зелёных угла к краям документа");hint.setPadding(20,20,20,20);layout.addView(hint);layout.addView(editor,new LinearLayout.LayoutParams(-1,(int)(a.getResources().getDisplayMetrics().heightPixels*.60f)));new AlertDialog.Builder(a).setTitle("Границы документа").setView(layout).setNegativeButton("Отмена",null).setPositiveButton("Применить",(d,v)->save.accept(editor.crop())).show();}
}
